/** The shape of the built-in meta pool (data.ts, regenerated by scripts/meta-refresh.ts). */
export interface MetaDeck {
  /** Limitless archetype id, e.g. 'dragapult-dusknoir'. */
  id: string;
  /** Archetype name, e.g. 'Dragapult Dusknoir'. */
  name: string;
  /** Fraction of players (0..1) on this archetype in the window. */
  share: number;
  /** Players on it in the window. */
  players: number;
  /** [catalogue card id ('sv06-130'), copies]; 60 cards. */
  list: [string, number][];
  /** The card name for each id in `list` (as printed): lets a reader audit the list, and lets the API refuse an id whose catalogue name differs. */
  names: Record<string, string>;
  /** Ids the sim's frame snapshot lacks, mapped from the PTCGL set alias only; their names are checked against the live catalogue at play time. */
  unverified?: string[];
  /** Where the representative list came from: no player names, ever. */
  from: { event: string; date: string; record: string; placing: number };
}

export interface MetaPool {
  /** The day the pool was built (YYYY-MM-DD). */
  asOf: string;
  source: { name: string; url: string; note: string };
  window: { days: number; minPlayers: number; events: number; players: number; from: string; to: string };
  format: 'standard';
  /** Most-played archetype first. */
  decks: MetaDeck[];
}
